def send_target(sock, joints, name):
    print(f'\n=== {name} ===')
    print([round(value, 4) for value in joints])
    command = f'movej({joints}, a={ACC}, v={VEL})\n'
    sock.sendall(command.encode('utf-8'))
    time.sleep(SLEEP_TARGET)


def send_path(sock, path, name):
    print(f'\n=== {name}: {len(path)} puntos ===')

    for index, joints in enumerate(path, start=1):
        print(f'{index}/{len(path)}', [round(v, 4) for v in joints])
        command = f'movej({joints}, a={ACC}, v={VEL})\n'
        sock.sendall(command.encode('utf-8'))
        time.sleep(SLEEP_POINT)


def send_gripper(sock, script_file, action):
    print(f'\n=== Pinza: {action} ===')

    if not script_file.exists():
        raise FileNotFoundError(script_file)

    with script_file.open('rb') as file:
        sock.sendall(file.read())

    time.sleep(SLEEP_GRIPPER)


